CREATE INDEX "bus_publication_outbox_message_move_idx" ON "bus_publication_outbox" ("project_id", json_extract("properties", '$.info.id'), json_extract("properties", '$.sourceSessionID'), json_extract("properties", '$.info.sessionID')) WHERE "event_type" = 'message.moved';
CREATE INDEX "bus_publication_outbox_part_removal_idx" ON "bus_publication_outbox" ("project_id", json_extract("properties", '$.messageID'), json_extract("properties", '$.sessionID'), json_extract("properties", '$.partID'), json_extract("properties", '$.partType')) WHERE "event_type" = 'message.part.removed';
